#include <iostream>
using namespace std;

class Superhero {
  public:
    void catch_phrase() {
      cout << "Superhero catchphrase!" << endl;
    }
};

class Batman: public Superhero {
  public:
    void catch_phrase() {
      cout << "I'm vengeance!" << endl;
    }
};

int main() {

    Batman bat;
    bat.catch_phrase();
    return 0;
}
